Dataflow model - Konkuretni izrazi – redosled kojim se pojavljuju ne menja značenje koda.
Svi se izvršavaju u paraleli. Kombinaciona logika.
entity ckt is
port (A: in BIT:=1;
end ckt;
B: in BIT; Y,Z: out BIT);
architecture ckt of ckt is
begin
B <= A and A;
Y<= A and B;
Z<= B after 10 ns;
end ckt;
entity ckt is
port (A: in BIT:=1;
end ckt;
B: in BIT; Y,Z: out BIT);
architecture ckt of ckt is
begin
Y<= A and B;
Z<= B after 10 ns;
B <= A and A;
end ckt;
A = 1, B = 0, Y = 0, Z = 0
Y = 1, Z = 1

entity latch is
port
(s,r : in bit;
q, nq : out bit);
s='0’, r='0', q='1', nq='0'
end latch;
architecture dataflow of latch is
begin
q<=r nor nq;
nq<=s nor q;
end dataflow;
r= ‘1’ pa r= ‘0’
start : r='0',s='0',q='1',nq='0’
round 1: r='1',s='0',q='1',nq='0', The value '0' is scheduled on q.
round 2: r='1',s='0',q='0',nq='0', The value '1' is scheduled on nq.
round 3: r='1',s='0',q='0',nq='1', No new events are scheduled.
round 4: r='0',s='0',q='0',nq='1', No new events are scheduled.
